import { useEffect, useRef, useState } from "react";
import HeroCard, { RX, RY } from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 6 }, // pure left

  { id: 2,  label: "DL Verification", angle: 120,   rotate: 9,   z: 7 }, // top-left       ┐
  { id: 3,  label: "KYC Check",       angle: 95,    rotate: -6,  z: 8 }, // top-center-l   | top 4
  { id: 4,  label: "Aadhaar",         angle: 68,    rotate: 5,   z: 9 }, // top-center-r   | (tighter arc)
  { id: 5,  label: "Face Match",      angle: 42,    rotate: -9,  z: 9 }, // top-right      ┘

  { id: 6,  label: "PAN Card",        angle: 18,    rotate: 12,  z: 8 }, // right-top
  { id: 7,  label: "Fraud Alert",     angle: 342,   rotate: -5,  z: 7 }, // right-bottom

  { id: 8,  label: "Bank Verify",     angle: 318,   rotate: 11,  z: 8 }, // bottom-right   ┐
  { id: 9,  label: "Credit Score",    angle: 292,   rotate: -5,  z: 9 }, // bottom-center-r| bottom 4
  { id: 10, label: "Background Chk",  angle: 265,   rotate: -10, z: 8 }, // bottom-center-l| (tighter arc)
  { id: 11, label: "Employment",      angle: 240,   rotate: 9,   z: 7 }, // bottom-left    ┘
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw] = useState(0);
  const sectionRef = useRef(null);

  // Scroll progress
  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(-el.getBoundingClientRect().top / (el.offsetHeight * 0.62), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Track viewport width for responsive logic
  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  const isMobile = vw < 600;
  const isTablet = vw >= 600 && vw < 1024;

  // --- Heading scale animation ---
  const headingScale = lerp(0.44, 1, ease(clamp(progress / 0.75, 0, 1)));

  // --- Subtitle fade/slide ---
  const subP = ease(clamp((progress - 0.60) / 0.30, 0, 1));

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* Cards layer — no wrapper scaling; each HeroCard self-sizes via vw prop */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            // overflow hidden prevents any card from causing a scrollbar
            overflow: "hidden",
          }}
        >
          {CARDS.map(c => (
            <HeroCard key={c.id} card={c} progress={progress} vw={vw} />
          ))}
        </div>

        {/* Hero text */}
        <div
          style={{
            position: "relative",
            zIndex: 20,
            textAlign: "center",
            transform: `scale(${headingScale})`,
            willChange: "transform",
            padding: "0 clamp(16px, 5vw, 120px)",
            maxWidth: 1800,
          }}
        >
          <h1
            style={{
              fontFamily: "'Inter', sans-serif",
              fontSize: "clamp(36px, 8.5vw, 148px)",
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
            }}
          >
            Deception from <br /> Click to the Doorstep
          </h1>

          <p
            style={{
              fontSize: "clamp(18px, 4vw, 45px)",
              fontWeight: 700,
              color: "white",
              margin: "24px 0 0 0",
              lineHeight: 1.2,
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>

          <p
            style={{
              color: "rgba(255,255,255,0.75)",
              fontSize: "clamp(13px, 1.1vw, 18px)",
              marginTop: 20,
              lineHeight: 1.7,
              maxWidth: 540,
              marginLeft: "auto",
              marginRight: "auto",
              opacity: subP,
              transform: `translateY(${lerp(20, 0, subP)}px)`,
            }}
          >
            Uncover the risks facing India's gig workforce
          </p>
        </div>
      </div>
    </div>
  );
}
